<template><section class="wiki-catalog"><div class="catalog-toolbar"><label class="catalog-search"><span>{{en?'Search blocks':'搜索方块'}}</span><input type="search" v-model="query" @input="page=1" :placeholder="en?'Name or block ID':'名称或方块 ID'"></label></div><p class="catalog-count">{{filtered.length}} {{en?'blocks':'种方块'}}</p><div class="catalog-grid"><article v-for="b in shown" :key="b.id" class="catalog-tile"><ModelPreview :url="b.model" :size="100" :label="nameOf(b,lang)"/><strong>{{nameOf(b,lang)}}</strong><code>{{b.id}}</code><p>{{en?'Hardness':'硬度'}} {{b.hardness}} · {{en?'Blast resistance':'爆炸抗性'}} {{b.blastResistance}}</p><button v-if="b.item!=='minecraft:air'" @click="openItem(b.item)">{{en?'Item and recipes':'查看物品与配方'}}</button><button v-else-if="catalog?.items[b.id]" @click="openItem(b.id)">{{en?'Related dish':'查看对应料理'}}</button><small v-else>{{en?'No standalone inventory item':'没有独立的背包物品'}}</small></article></div><nav class="catalog-pagination"><button :disabled="page===1" @click="page--">{{en?'Previous':'上一页'}}</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">{{en?'Next':'下一页'}}</button></nav></section></template>
<script setup lang="ts">
import{ref,computed,onMounted,watch}from'vue';import{useData}from'vitepress';import{getData,nameOf,openItem}from'../lib/wiki';import ModelPreview from'./ModelPreview.vue';const{lang}=useData(),en=computed(()=>lang.value.startsWith('en')),catalog=ref<any>(),query=ref(''),page=ref(1);const filtered=computed<any[]>(()=>Object.values(catalog.value?.blocks??{}).filter((b:any)=>[b.id,b.nameZh,b.nameEn].join(' ').toLowerCase().includes(query.value.toLowerCase()))),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/24))),shown=computed(()=>filtered.value.slice((page.value-1)*24,page.value*24));watch(pages,()=>page.value=Math.min(page.value,pages.value));onMounted(async()=>catalog.value=await getData());
</script>
